mapper.select:
SELECT ,
       u.nick_name AS seller_nick_name,
       u.avatar AS seller_avatar
FROM product p
LEFT JOIN sys_user u ON p.seller_id = u.user_id

    AND p.tenant_id = #{tenantId}
    AND p.status = #{status}
    AND p.cat_l1 = #{catL1}
    AND p.city = #{city}

        AND MATCH(p.title, p.description) AGAINST(#{keyword})

    AND p.price >= #{priceMin}
    AND p.price <= #{priceMax}
    AND p.`condition` = #{condition}


    ORDER BY p.price ASC
    ORDER BY p.price DESC
    ORDER BY p.view_count DESC, p.publish_time DESC
    ORDER BY p.is_pinned DESC, p.publish_time DESC

LIMIT #{limit}

SELECT ,
       u.nick_name AS seller_nick_name,
       u.avatar AS seller_avatar
FROM product p
LEFT JOIN sys_user u ON p.seller_id = u.user_id
WHERE p.seller_id = #{sellerId}
AND p.tenant_id = #{tenantId}
AND p.status = 'onsale'
AND p.product_id != #{excludeProductId}
ORDER BY p.publish_time DESC
LIMIT #{limit}

SELECT , p.hot_score,
       u.nick_name AS seller_nick_name,
       u.avatar AS seller_avatar
FROM product p
LEFT JOIN sys_user u ON p.seller_id = u.user_id
WHERE p.status = 'onsale'
AND p.tenant_id = #{tenantId}
  AND p.cat_l1 = #{catL1}
  AND p.product_id != #{excludeProductId}
ORDER BY p.hot_score DESC, p.publish_time DESC
LIMIT #{limit}

