UPDATE product
title = #{title}, cover = #{cover}, images = #{images}, price = #{price}, original_price = #{originalPrice}, `condition` = #{condition}, cat_l1 = #{catL1}, cat_l2 = #{catL2}, shipping_method = #{shippingMethod}, shipping_fee = #{shippingFee}, stock = #{stock}, status = #{status}, description = #{description}, location = #{location}, city = #{city}, purchase_date = #{purchaseDate}, update_time = NOW()
WHERE product_id = #{productId} AND tenant_id = #{tenantId}

UPDATE product
