    audit_reject_reason = #{rejectReason},
    update_time = NOW()
WHERE product_id = #{productId}
AND tenant_id = #{tenantId}

UPDATE product
SET status = #{status},
    update_time = NOW()
WHERE product_id = #{productId}
  AND status IN

    #{s}

AND tenant_id = #{tenantId}

UPDATE product SET
    status = IF(status IN ('locked', 'sold'), 'onsale', status),
    stock = stock + 1, update_time = NOW()
WHERE product_id = #{productId}
AND tenant_id = #{tenantId}

UPDATE product SET status = 'sold', update_time = NOW()
WHERE product_id = #{productId} AND stock = 0 AND status = 'locked'
AND tenant_id = #{tenantId}

